#!/usr/bin/env bash
# Scoped Slither run (CI and local). The UltraHonk verifiers generated by circuits/scripts/build.sh crash Slither's
# parser (constant-sized arrays in structs), so they are left out of the build Slither reads: every other contract
# in src/ is compiled into a separate output directory and analysed from there. Poseidon2 and HiddenConstants
# (hand-written, imported by the Hidden Vault) stay in. Findings in vendored libraries and testnet mocks are
# filtered (slither.config.json).
#
#   bash script/slither.sh      # fails on any Medium or High finding not reviewed in slither.triage.json
#
# Each reviewed finding is accepted per detector and function, with a reason, in slither.triage.json; the gate
# (script/slither-gate.py) fails on anything new. Requires slither-analyzer (pip), forge and python3.
set -euo pipefail
cd "$(dirname "$0")/.."

out="out-slither"
cache="cache-slither"
report="${SLITHER_JSON:-$out/slither.json}"
files=()
while IFS= read -r f; do files+=("$f"); done < <(
  find src -name '*.sol' -not -path 'src/consumer/verifiers/*Verifier.sol' | sort
)

forge build --no-lint --build-info --skip test --skip script --out "$out" --cache-path "$cache" "${files[@]}" >/dev/null
rm -f "$report"
# Slither exits non-zero whenever it reports anything; the gate below decides.
slither . --config-file slither.config.json --foundry-ignore-compile --foundry-out-directory "$out" \
  --json "$report" >/dev/null 2>&1 || true
[ -s "$report" ] || { echo "slither produced no report" >&2; exit 2; }
python3 script/slither-gate.py "$report" slither.triage.json
